<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Observability {
    /** @var list<string> Captured log messages for testing. */
    $GLOBALS['__captured_error_log'] = [];

    function error_log(string $message): void
    {
        $GLOBALS['__captured_error_log'][] = $message;
    }
}

namespace {
    use Monolog\Handler\TestHandler;
    use Monolog\Logger as MonologLogger;
    use PHPUnit\Framework\TestCase;
    use Psr\Container\ContainerInterface;
    use Psr\Log\LoggerInterface;
    use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;

    /**
     * Unit tests for LoggerAwareTrait.
     */
    final class LoggerAwareTraitUnitTest extends TestCase
    {
        protected function setUp(): void
        {
            $GLOBALS['__captured_error_log'] = [];
        }

        /**
         * Ensures missing logger falls back without errors.
         */
        public function testSetLoggerFromContainerMissing(): void
        {
            /*
             * Arrange: build a trait consumer and a container with no logger.
             */
            $service = new class () {
                use LoggerAwareTrait;
            };
            $container = $this->createMock(ContainerInterface::class);
            $container->expects($this->once())
                ->method('has')
                ->with(LoggerInterface::class)
                ->willReturn(false);
            $container->expects($this->never())->method('get');

            /*
             * Act: resolve the logger and log a message.
             */
            $service->setLoggerFromContainer($container);
            $service->logInfo('fallback');

            /*
             * Assert: confirm fallback logging path completed via error_log.
             */
            $this->assertCount(1, $GLOBALS['__captured_error_log']);
            $this->assertSame('INFO: fallback []', $GLOBALS['__captured_error_log'][0]);
        }

        /**
         * Ensures all log levels use the fallback when no logger is set.
         */
        public function testAllLogLevelsFallbackToErrorLog(): void
        {
            /*
             * Arrange: create a trait consumer without a logger.
             */
            $service = new class () {
                use LoggerAwareTrait;
            };

            /*
             * Act: invoke every log level with context.
             */
            $service->logEmergency('msg-emergency', ['k' => 'v']);
            $service->logAlert('msg-alert', ['k' => 'v']);
            $service->logCritical('msg-critical', ['k' => 'v']);
            $service->logError('msg-error', ['k' => 'v']);
            $service->logWarning('msg-warning', ['k' => 'v']);
            $service->logNotice('msg-notice', ['k' => 'v']);
            $service->logInfo('msg-info', ['k' => 'v']);
            $service->logDebug('msg-debug', ['k' => 'v']);

            /*
             * Assert: verify each level produced the expected fallback output.
             */
            $expected = [
                'EMERGENCY: msg-emergency {"k":"v"}',
                'ALERT: msg-alert {"k":"v"}',
                'CRITICAL: msg-critical {"k":"v"}',
                'ERROR: msg-error {"k":"v"}',
                'WARNING: msg-warning {"k":"v"}',
                'NOTICE: msg-notice {"k":"v"}',
                'INFO: msg-info {"k":"v"}',
                'DEBUG: msg-debug {"k":"v"}',
            ];
            $this->assertSame($expected, $GLOBALS['__captured_error_log']);
        }

        /**
         * Ensures fallback logs without context omit the context string.
         */
        public function testFallbackWithEmptyContext(): void
        {
            /*
             * Arrange: create a trait consumer without a logger.
             */
            $service = new class () {
                use LoggerAwareTrait;
            };

            /*
             * Act: log a message without context.
             */
            $service->logInfo('no-context');

            /*
             * Assert: verify the fallback output includes empty context.
             */
            $this->assertSame('INFO: no-context []', $GLOBALS['__captured_error_log'][0]);
        }

        /**
         * Ensures log methods delegate to the configured logger.
         */
        public function testLoggerMethodsCallLogger(): void
        {
            /*
             * Arrange: create a trait consumer with a mocked logger.
             */
            $service = new class () {
                use LoggerAwareTrait;
            };

            $logger = $this->createMock(LoggerInterface::class);
            $logger->expects($this->once())->method('emergency')->with('e', ['a' => 1]);
            $logger->expects($this->once())->method('alert')->with('a', ['b' => 2]);
            $logger->expects($this->once())->method('critical')->with('c', ['c' => 3]);
            $logger->expects($this->once())->method('error')->with('e2', ['d' => 4]);
            $logger->expects($this->once())->method('warning')->with('w', ['e' => 5]);
            $logger->expects($this->once())->method('notice')->with('n', ['f' => 6]);
            $logger->expects($this->once())->method('info')->with('i', ['g' => 7]);
            $logger->expects($this->once())->method('debug')->with('d', ['h' => 8]);

            /*
             * Act: set the logger and invoke all log methods.
             */
            $service->setLogger($logger);
            $service->logEmergency('e', ['a' => 1]);
            $service->logAlert('a', ['b' => 2]);
            $service->logCritical('c', ['c' => 3]);
            $service->logError('e2', ['d' => 4]);
            $service->logWarning('w', ['e' => 5]);
            $service->logNotice('n', ['f' => 6]);
            $service->logInfo('i', ['g' => 7]);
            $service->logDebug('d', ['h' => 8]);

            /*
             * Assert: confirm each logger method was invoked.
             */
        }

        /**
         * Ensures a MonologLogger from the container is wrapped with a source processor.
         */
        public function testSetLoggerFromContainerWithMonologLoggerAddsSourceProcessor(): void
        {
            /*
             * Arrange: create a real MonologLogger with a test handler.
             */
            $handler = new TestHandler();
            $monolog = new MonologLogger('app', [$handler]);

            $service = new class () {
                use LoggerAwareTrait;

                public function getLogger(): ?LoggerInterface
                {
                    return $this->logger;
                }
            };

            $container = $this->createMock(ContainerInterface::class);
            $container->method('has')->with(LoggerInterface::class)->willReturn(true);
            $container->method('get')->with(LoggerInterface::class)->willReturn($monolog);

            /*
             * Act: resolve the logger from the container.
             */
            $service->setLoggerFromContainer($container);

            /*
             * Assert: the stored logger is a MonologLogger with source injected on log.
             */
            $logger = $service->getLogger();
            $this->assertInstanceOf(MonologLogger::class, $logger);

            $service->logInfo('hello');
            $records = $handler->getRecords();
            $this->assertNotEmpty($records);
            $this->assertArrayHasKey('source', $records[0]['extra']);
        }

        /**
         * Ensures logger resolution from container uses the logger.
         */
        public function testSetLoggerFromContainerUsesLogger(): void
        {
            /*
             * Arrange: create a container that returns a logger.
             */
            $service = new class () {
                use LoggerAwareTrait;
            };

            $logger = $this->createMock(LoggerInterface::class);
            $logger->expects($this->once())->method('info')->with('ready', []);

            $container = $this->createMock(ContainerInterface::class);
            $container->expects($this->once())
                ->method('has')
                ->with(LoggerInterface::class)
                ->willReturn(true);
            $container->expects($this->once())
                ->method('get')
                ->with(LoggerInterface::class)
                ->willReturn($logger);

            /*
             * Act: resolve the logger from the container and log a message.
             */
            $service->setLoggerFromContainer($container);
            $service->logInfo('ready');

            /*
             * Assert: confirm the logger received the message.
             */
        }
    }
}
